#' Moments of Age Distributions
#'
#' Returns sample-level summary of moments of an age distribution, including
#' diseprsion estimates adjusted for excess variances produced by dating
#' uncertainty. Requires an object of the class 'postdist' generated by
#' function \code{\link{postdist}}
#'
#' @details If argument 'simple' is set to TRUE (default), the function returns
#' a dataframe with estimates for the analyzed sample. If argument 'simple' is
#' set to FALSE, the function returns a list
#'
#' The following estimates are returned:
#'
#' median.age - median age of a sample calculated from mean or median ages
#' of posterior distributions of individual ages
#'
#' mean.age - mean age of a sample calculated from mean or median ages
#' of posterior distributions of individual ages
#'
#' STD2 - two standard deviations of a sample calculated from mean or median
#' ages of posterior distributions of individual ages
#'
#' IQR - interquartile range calculated from mean or median ages of posterior
#' distributions of individual ages
#'
#' ETA2SD - Estimated Time-Averaging (2 standard deviations) corrected for
#' dating uncertainty calculated as 2 * square root of TAV-AEV
#' (see Ritter et al. 2023)
#'
#' ETA50 - Estimated IQR corrected for dating uncertainty computed as ETA/2
#' multiplied by iq.age/std.age (see Tomasovych et al. 2023)
#'
#' L2 - L-dispersion calculated from mean or median ages of posterior
#' distributions using function \code{\link[lmom]{samlmu}}
#' from package "lmom". NOTE: This estimate is not corrected for dating uncertainty.
#'
#' G1 - skewness, the third moment about the mean calculated from mean or
#' median ages of posterior distributions
#'
#' L3 - L-skewness calculated from mean or median ages of posterior
#' distributions using function \code{\link[lmom]{samlmu}}
#' from package "lmom".
#'
#' @param x An object of the class "postdist" returned by the \code{\link{postdist}} function
#'
#' @param use.median A logical argument (default=TRUE) to determine whether to
#' use median age (TRUE) or mean age (FALSE) to estimate central tendency of the
#' posterior distribution of age probabilities
#'
#' @param simple A logical argument (default=TRUE) to determine if additional
#' information should be returned by the function.
#'
#' @return A dataframe with sample-level statistics (if simple=TRUE) or
#' a list with five items (if simple=FALSE):
#'   \item{my.stats}{returns a dataframe (if simple = TRUE) or the first item in
#'   the list of items (if simple = FALSE). This is a single set of numerical values
#'   providing summary statistics for a given sample}
#'   \item{ages}{returns age estimates (mean or median ages) for individual
#'   observations, if simple = FALSE}
#'   \item{n}{returns the number of age dates in a sample, if simple = FALSE}
#'   \item{num.replic.ages}{returns the number of mcmc replicate samples
#'   from the posterior probability distibution of each age date, if simple = FALSE}
#'   \item{age.estimate}{returns the information if median or mean of the
#'   posterior probability distribution was used to derive an estimated
#'   specimen age, if simple = FALSE}
#'
#' @examples
#'
#' out1 <- postdist(age=florida$post$cal.BP, prob=florida$post$probability,
#' id=florida$post$UniqueID, size=10000)
#'
#' tastats(out1)
#'
#' @importFrom lmom samlmu
#' @importFrom stats var sd median IQR
#'
#' @export
#'
#' @references Hosking, JRM, 2023, L-Moments. R package, version 3.0.
#' https://CRAN.R-project.org/package=lmom
#'
#' Ritter, M, Erthal F, Kosnik, MA, Kowalewski, M, Coimbra, CJ,
#' Caron, F, Kaufman, DS, 2023, Onshore-offshore trends in the temporal
#' resolution of molluscan death assemblages: how age-frequency
#' distributions reveal Quaternary sea-level history.
#' Palaios, 38: 148-157. http://dx.doi.org/10.2110/palo.2021.041
#'
#' Tomašových, A., Kidwell, S.M. and Dai, R., (2023), A downcore increase
#' in time averaging is the null expectation from the transit of death assemblages
#' through a mixed layer. Paleobiology, 49(3), pp.527-562.
#' https://doi.org/10.1017/pab.2022.42
#'

tastats <- function(x, use.median=TRUE, simple=TRUE) {
  if (!('postdist' %in% class(x))) stop('object of the class "postdist" required')
  nspec <- nrow(x) # number of specimens
  if (use.median) y <- apply(x, 1, stats::median)
  if (!use.median) y <- apply(x, 1, function(x) sum(x)/length(x))
  ifelse(use.median, age.estimate <- 'median', age.estimate <- 'mean')
  iter <- ncol(x) # number of replicate ages in Monte Carlo distributions
  median.age <- stats::median(y)
  mean.age <- sum(y)/length(y)
  std.age <- stats::sd(y)
  iq.age <- stats::IQR(y)
  AEV <- mean(apply(x, 1, var))
  TAV <- stats::var(as.vector(x))
  ETA <- 2*sqrt(TAV - AEV)
  IQR <- (ETA/2)*(iq.age/std.age)
  g1 <- (sum((y-mean(y))^3)/length(y)) / stats::var(y)^(3/2)
  lmom <- as.numeric(lmom::samlmu(y))[2:3]
  l2 <- lmom[1]
  l3 <- lmom[2]
  my.stats <- data.frame(median.age, mean.age, STD2=2*std.age, IQR=iq.age,
                         ETA2SD=ETA, ETA50=IQR, L2=l2, G1=g1, L3=l3)
  rownames(my.stats) <- 'estimate'
  if (simple) return(my.stats)
  if (!simple) return(list(my.stats, ages=y, n=nspec, num.replic=iter,
                           age.estimate))
}
